const BASE_URL = "https://api.mercadopago.com";
// Token de teste (TEST-...) ou de produção (APP_USR-...): a URL é a mesma, o prefixo do token é que muda o ambiente.
const ACCESS_TOKEN = process.env.MP_ACCESS_TOKEN ?? "<<SEU_ACCESS_TOKEN>>";

async function mp<T>(
  method: string,
  path: string,
  opts: { query?: Record<string, string | number>; body?: unknown; idempotency?: boolean; headers?: Record<string, string> } = {},
  tentativas = 4,
): Promise<T | null> {
  const url = new URL(BASE_URL + path);
  for (const [k, v] of Object.entries(opts.query ?? {})) url.searchParams.set(k, String(v));
  const idempotencyKey = opts.idempotency ? crypto.randomUUID() : undefined; // a MESMA chave em toda retentativa
  for (let i = 0; i < tentativas; i++) {
    const res = await fetch(url, {
      method,
      headers: {
        Authorization: `Bearer ${ACCESS_TOKEN}`,
        "Content-Type": "application/json",
        ...(idempotencyKey ? { "X-Idempotency-Key": idempotencyKey } : {}),
        ...(opts.headers ?? {}),
      },
      body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
    });
    const ultima = i === tentativas - 1;
    if (res.status === 429 && !ultima) {
      await new Promise((r) => setTimeout(r, (Number(res.headers.get("Retry-After") ?? 2 ** i) + 1) * 1000));
      continue;
    }
    if (res.status >= 500 && method === "GET" && !ultima) {
      await new Promise((r) => setTimeout(r, 2 ** i * 1000));
      continue;
    }
    const texto = await res.text();
    if (!res.ok) throw new Error(`Mercado Pago HTTP ${res.status} (X-Request-Id=${res.headers.get("X-Request-Id")}): ${texto}`);
    return texto ? (JSON.parse(texto) as T) : null;
  }
  throw new Error("Mercado Pago: tentativas esgotadas");
}


mp("POST", "/oauth/token", { body: {
  "client_id": "<<SEU_CLIENT_ID>>",
  "client_secret": "<<SEU_CLIENT_SECRET>>",
  "grant_type": "authorization_code",
  "code": "<CODE_RECEBIDO_NO_REDIRECT>",
  "redirect_uri": "https://minha-plataforma.example.com/mp/callback"
} }).then(console.log).catch(console.error);

